      title: "The Stranger",
      year: 1946,
      genres: ["Film-Noir", "Crime", "Mystery", "Drama"],
      runtime: "95 min",
      rating: "8.1",
      director: "Orson Welles",
      posterUrl: "https://archive.org/services/img/TheStranger_0",
      streamUrl: "https://archive.org/download/TheStranger_0/The_Stranger_1946_512kb.mp4",
      fileName: "The_Stranger_1946.mp4",
