      copyrightStatus: "Public Domain"
    },
    {
      id: "battleship_potemkin_1925",
      identifier: "BattleshipPotemkin",
      title: "Battleship Potemkin",
      year: 1925,
      genres: ["Drama", "History", "Silent"],
      runtime: "75 min",
      rating: "8.8",
      director: "Sergei Eisenstein",
      posterUrl: "https://archive.org/services/img/BattleshipPotemkin",
      streamUrl: "https://archive.org/download/BattleshipPotemkin/Battleship_Potemkin_1925_512kb.mp4",
      fileName: "BattleshipPotemkin_1925.mp4",
      fileSize: "530 MB",
      copyrightStatus: "Public Domain"
    },
    {
      id: "carnival_of_souls_1962",
      identifier: "CarnivalofSouls",
      title: "Carnival of Souls",
      year: 1962,
      genres: ["Horror", "Mystery"],
      runtime: "78 min",
      rating: "7.9",
      director: "Herk Harvey",
      posterUrl: "https://archive.org/services/img/CarnivalofSouls",
      streamUrl: "https://archive.org/download/CarnivalofSouls/Carnival_of_Souls_1962_512kb.mp4",
      fileName: "Carnival_of_Souls_1962.mp4",
      fileSize: "490 MB",
      copyrightStatus: "Public Domain"
    },
    {
      id: "big_buck_bunny_2008",
      identifier: "BigBuckBunny_328",
      title: "Big Buck Bunny",
      year: 2008,
      genres: ["Animation", "Comedy"],
      runtime: "10 min",
      rating: "8.5",
      director: "Sacha Goedegebure",
      posterUrl: "https://archive.org/services/img/BigBuckBunny_328",
      streamUrl: "https://archive.org/download/BigBuckBunny_328/big_buck_bunny_1080p_surround.mp4",
      fileName: "Big_Buck_Bunny_1080p.mp4",
      fileSize: "280 MB",
      copyrightStatus: "Creative Commons"
    }
  ];

  let currentCategory = 'all';
  let currentSearch = '';
  let myList = JSON.parse(localStorage.getItem('cinevault_my_list') || '[]');
  let currentModalMovie = null;

  function init() {
    updateMyListBadge();
    renderMovies();
  }

  function updateMyListBadge() {
    const badge = document.getElementById('myListBadge');
    if (badge) badge.innerText = myList.length;
  }

  function toggleMyList(identifier) {
    const idx = myList.indexOf(identifier);
    if (idx >= 0) {
      myList.splice(idx, 1);
    } else {
      myList.unshift(identifier);
    }
    localStorage.setItem('cinevault_my_list', JSON.stringify(myList));
    updateMyListBadge();
    renderMovies();
  }

  function showCategory(cat) {
    currentCategory = cat;
    ['all', 'Horror', 'Sci-Fi', 'Comedy', 'Drama', 'Mystery', 'mylist'].forEach(t => {
      const btn = document.getElementById('tab-' + t);
      if (btn) {
        if (t === cat) {
          btn.className = 'px-3.5 py-1.5 rounded-lg text-xs font-bold transition-all bg-blue-600 text-white';
        } else {
          btn.className = 'px-3.5 py-1.5 rounded-lg text-xs font-semibold text-slate-400 hover:text-white bg-slate-900 hover:bg-slate-800';
        }
      }
    });
    renderMovies();
  }

  function handleSearch(val) {
    currentSearch = (val || '').toLowerCase().trim();
    renderMovies();
  }

  function pickRandomMovie() {
    const randomIndex = Math.floor(Math.random() * MOVIES.length);
    const m = MOVIES[randomIndex];
    playMovie(m.identifier);
  }

  function renderMovies() {
    const grid = document.getElementById('moviesGrid');
    const emptyMsg = document.getElementById('emptyMessage');
    const countLabel = document.getElementById('movieCountLabel');

    let filtered = MOVIES.filter(m => {
      if (currentCategory === 'mylist') {
        if (!myList.includes(m.identifier)) return false;
      } else if (currentCategory !== 'all') {
        if (!m.genres.includes(currentCategory)) return false;
      }
      if (currentSearch) {
        const matchTitle = m.title.toLowerCase().includes(currentSearch);
        const matchDir = m.director.toLowerCase().includes(currentSearch);
        const matchGenre = m.genres.some(g => g.toLowerCase().includes(currentSearch));
        if (!matchTitle && !matchDir && !matchGenre) return false;
      }
      return true;
    });

    countLabel.innerText = `${filtered.length} Movies Available`;

    if (filtered.length === 0) {
      grid.innerHTML = '';
      emptyMsg.classList.remove('hidden');
      return;
    }

    emptyMsg.classList.add('hidden');
    grid.innerHTML = filtered.map(m => {
      const inList = myList.includes(m.identifier);
      return `
        <div class="group relative flex flex-col rounded-xl overflow-hidden bg-slate-900 border border-slate-800 shadow-md hover:shadow-2xl hover:shadow-blue-900/40 transition-all transform hover:-translate-y-1">
          <div class="relative aspect-[2/3] overflow-hidden bg-slate-950 cursor-pointer" onclick="playMovie('${m.identifier}')">
            <img
              src="${m.posterUrl}"
              alt="${m.title}"
              loading="lazy"
              class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
              onerror="this.onerror=null; this.src='https://archive.org/services/img/${m.identifier}'"
            />
            <div class="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/20 to-transparent opacity-80"></div>

            <div class="absolute top-2 left-2 flex gap-1">
              <span class="bg-blue-600 text-white text-[9px] font-extrabold px-1.5 py-0.5 rounded">FREE</span>
              <span class="bg-emerald-900/90 text-emerald-200 text-[9px] font-bold px-1.5 py-0.5 rounded">${m.copyrightStatus}</span>
            </div>

            <div class="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
              <div class="w-10 h-10 rounded-full bg-blue-600 text-white flex items-center justify-center shadow-lg">
                <svg class="w-5 h-5 fill-current ml-0.5" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
              </div>
            </div>
          </div>

          <div class="p-3 flex flex-col justify-between flex-1 gap-2 bg-slate-900">
            <div>
              <h4 class="text-white font-bold text-xs line-clamp-1 group-hover:text-blue-400 transition-colors" title="${m.title}">${m.title}</h4>
              <div class="flex items-center justify-between text-[10px] text-slate-400 mt-1">
                <span>${m.year} • ${m.genres[0]}</span>
                <span class="text-amber-400 font-bold">★ ${m.rating}</span>
              </div>
            </div>

            <div class="grid grid-cols-2 gap-1.5 pt-1">
              <button
                onclick="playMovie('${m.identifier}')"
                class="bg-blue-600 hover:bg-blue-500 text-white text-[11px] font-bold py-1 px-2 rounded-lg transition-colors cursor-pointer"
              >
                PLAY
              </button>
              <button
                onclick="openDownloadModal('${m.identifier}')"
                class="bg-slate-800 hover:bg-slate-700 text-slate-200 hover:text-white text-[11px] font-semibold py-1 px-2 rounded-lg border border-slate-700 transition-colors cursor-pointer"
              >
                DOWNLOAD
              </button>
            </div>

            <div class="flex items-center justify-between pt-1 border-t border-slate-800/80 text-[10px] text-slate-400">
              <button onclick="toggleMyList('${m.identifier}')" class="hover:text-white flex items-center gap-1 cursor-pointer">
                ${inList ? '★ Saved' : '+ My List'}
              </button>
              <button onclick="shareMovieWhatsApp('${m.identifier}')" class="text-emerald-400 hover:text-emerald-300 flex items-center gap-1 cursor-pointer">
                Share
              </button>
            </div>
          </div>
        </div>
      `;
    }).join('');
  }

  function playMovie(identifier) {
    const movie = MOVIES.find(m => m.identifier === identifier);
    if (!movie) return;

    const modal = document.getElementById('playerModal');
    const video = document.getElementById('videoElement');
    const title = document.getElementById('playerTitle');
    const subtitle = document.getElementById('playerSubtitle');

    title.innerText = movie.title + ' (' + movie.year + ')';
    subtitle.innerText = 'Director: ' + movie.director + ' • ' + movie.copyrightStatus;

    video.src = movie.streamUrl;
    video.load();
    video.play().catch(() => {});

    modal.classList.remove('hidden');
  }

  function closePlayer() {
    const modal = document.getElementById('playerModal');
    const video = document.getElementById('videoElement');
    video.pause();
    video.src = '';
    modal.classList.add('hidden');
  }

  function openDownloadModal(identifier) {
    const movie = MOVIES.find(m => m.identifier === identifier);
    if (!movie) return;

    currentModalMovie = movie;
    const modal = document.getElementById('downloadModal');
    document.getElementById('dlMovieTitle').innerText = movie.title + ' (' + movie.year + ')';
    document.getElementById('dlFileName').innerText = movie.fileName;
    document.getElementById('dlFileSize').innerText = movie.fileSize;

    const primaryBtn = document.getElementById('dlPrimaryBtn');
    primaryBtn.onclick = () => {
      const a = document.createElement('a');
      a.href = movie.streamUrl;
      a.setAttribute('download', movie.fileName);
      a.setAttribute('target', '_blank');
      document.body.appendChild(a);
      a.click();
      setTimeout(() => { if (document.body.contains(a)) document.body.removeChild(a); }, 200);
      window.open(movie.streamUrl, '_blank');
    };

    modal.classList.remove('hidden');
  }

  function closeDownloadModal() {
    document.getElementById('downloadModal').classList.add('hidden');
    currentModalMovie = null;
  }

  function copyDownloadUrl() {
    if (!currentModalMovie) return;
    navigator.clipboard.writeText(currentModalMovie.streamUrl).then(() => {
      const btn = document.getElementById('dlCopyBtn');
      btn.innerText = 'Copied!';
      setTimeout(() => btn.innerText = 'Copy URL', 2000);
    });
  }

  function shareOnWhatsApp() {
    const text = encodeURIComponent(
      "🎬 CineVault - Free & Legal Movies Streaming & Direct Download:\n" + window.location.href
    );
    window.open('https://api.whatsapp.com/send?text=' + text, '_blank');
  }

  function shareMovieWhatsApp(identifier) {
    const movie = MOVIES.find(m => m.identifier === identifier);
    if (!movie) return;
    const text = encodeURIComponent(
      `🎬 CineVault Legal Movie:\n"${movie.title} (${movie.year})" [${movie.copyrightStatus}]\nDownload & Stream: ${movie.streamUrl}`
    );
    window.open('https://api.whatsapp.com/send?text=' + text, '_blank');
  }

  window.onload = init;
//
